`MessageRow`는 `fillMaxWidth()`로 가로 전체를 차지하기 때문에, `DropdownMenu`에 오프셋을 지정하지 않으면 사용자가 메시지 우측을 클릭하더라도 메뉴가 항상 화면 맨 왼쪽에 나타나게 되어 사용성이 떨어집니다. 우클릭 시의 마우스 포인터 위치(`pressOffset`)를 저장하고 이를 `DropdownMenu`의 `offset`으로 전달하여 클릭한 위치에 메뉴가 나타나도록 개선하는 것을 권장합니다.

```kotlin
    var contextMenuVisible by remember { mutableStateOf(false) }
    var pressOffset by remember { mutableStateOf(androidx.compose.ui.unit.DpOffset.Zero) }
    val density = LocalDensity.current
    @Suppress("DEPRECATION")
    val clipboardManager = LocalClipboardManager.current
    val hoverInteraction = remember { MutableInteractionSource() }
    val isHovered by hoverInteraction.collectIsHoveredAsState()}

    Box(
        modifier = Modifier
            .fillMaxWidth()
            .hoverable(hoverInteraction)
            .background(
                when {
                    isEditing -> MaterialTheme.colorScheme.primary.copy(alpha = 0.06f)
                    isHovered -> MaterialTheme.colorScheme.onSurface.copy(alpha = 0.045f)
                    else -> Color.Transparent
                }
            )
            .pointerInput(message.id) {
                awaitPointerEventScope {
                    while (true) {
                        val event = awaitPointerEvent()
                        if (event.type == PointerEventType.Press) {
                            val btn = event.buttons
                            if (btn.isSecondaryPressed) {
                                val change = event.changes.firstOrNull()
                                if (change != null) {
                                    val position = change.position
                                    pressOffset = with(density) {
                                        androidx.compose.ui.unit.DpOffset(position.x.toDp(), position.y.toDp())
                                    }
                                }
                                contextMenuVisible = true
                            }
                        }
                    }
